-- Extended cutting regression fixtures. No game data is changed.
begin;
do $$
begin
assert public.mg_cut_check('{"width": 3, "height": 2, "cells": [[0, 0], [1, 0], [2, 0], [0, 1], [1, 1], [2, 1]], "parts": 2, "rule": "congruent", "ways": 3}'::jsonb,'{"variants": [{"cuts": ["0,0|0,1", "1,0|1,1", "2,0|2,1"]}, {"cuts": ["1,0|2,0", "1,0|1,1", "0,1|1,1"]}, {"cuts": ["0,0|1,0", "1,0|1,1", "1,1|2,1"]}]}'::jsonb)='yes', 'three different ways';
assert public.mg_cut_check('{"width": 3, "height": 2, "cells": [[0, 0], [1, 0], [2, 0], [0, 1], [1, 1], [2, 1]], "parts": 2, "rule": "congruent", "ways": 3}'::jsonb,'{"variants": [{"cuts": ["0,0|0,1", "1,0|1,1", "2,0|2,1"]}, {"cuts": ["1,0|2,0", "1,0|1,1", "0,1|1,1"]}, {"cuts": ["1,0|2,0", "1,0|1,1", "0,1|1,1"]}]}'::jsonb)='no', 'duplicate way rejected';
assert public.mg_cut_check('{"width": 3, "height": 3, "cells": [[0, 0], [1, 0], [2, 0], [0, 1], [1, 1], [2, 1], [0, 2], [1, 2], [2, 2]], "parts": 2, "rule": "congruent", "remove_cells": 1}'::jsonb,'{"cuts": ["1,0|2,0", "0,2|1,2"], "removed": ["1,1"]}'::jsonb)='yes', 'one excluded cell';
assert public.mg_cut_check('{"width": 3, "height": 3, "cells": [[0, 0], [1, 0], [2, 0], [0, 1], [1, 1], [2, 1], [0, 2], [1, 2], [2, 2]], "parts": 2, "rule": "congruent", "remove_cells": 1}'::jsonb,'{"cuts": ["1,0|2,0", "0,2|1,2"]}'::jsonb)='no', 'missing excluded cell';
assert public.mg_cut_check('{"width": 2, "height": 2, "cells": [[0, 0], [1, 0], [0, 1], [1, 1]], "parts": 2, "rule": "congruent", "color_rule": "each", "colors": {"0,0": "green", "1,0": "green", "0,1": "red", "1,1": "red"}}'::jsonb,'{"cuts": ["0,0|1,0", "0,1|1,1"]}'::jsonb)='yes', 'one of every color';
